```tsx
import { useEffect, useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Outcome = 'ok' | 'rejected';

const SAMPLES: Record<
  Outcome,
  { orden: number; comis: number; movim: number; mens: string }
> = {
  ok: {
    orden: 1042,
    comis: 1250.5,
    movim: 80012345,
    mens: 'PAGO APLICADO CORRECTAMENTE',
  },
  rejected: {
    orden: 1043,
    comis: 0,
    movim: 0,
    mens: 'PAGO RECHAZADO - SALDO INSUFICIENTE',
  },
};

// Format 9(7): zero padded, 7 digits
const formatOrden = (n: number) => String(n).padStart(7, '0');

// Format ZZZ,ZZ9.99: thousands separator, no leading zeros, 2 decimals
const formatComis = (n: number) =>
  n.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });

// Format Z(9)9: no leading zeros, up to 10 digits
const formatMovim = (n: number) => String(n);

export default function PagoResultado({
  navigate,
}: {
  navigate: (to: string) => void;
}) {
  const [outcome, setOutcome] = useState<Outcome>('ok');
  const data = SAMPLES[outcome];

  const newPayment = () => navigate('SCR-PAGOORD');
  const goMenu = () => navigate('SCR-PAGOMEN');

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const tag = target?.tagName;
      if (e.key === 'F3') {
        e.preventDefault();
        navigate('SCR-PAGOMEN');
      } else if (
        e.key === 'Enter' &&
        tag !== 'BUTTON' &&
        tag !== 'SELECT' &&
        tag !== 'A'
      ) {
        navigate('SCR-PAGOORD');
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [navigate]);

  return (
    <Screen
      title="Resultado del pago"
      code="SCR-PAGORES"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nuevo pago', onPress: newPayment, primary: true },
            { key: 'PF3', label: 'Menú', onPress: goMenu },
          ]}
        />
      }
    >
      <Stack>
        <div data-field="RMENS">
          <Alert tone={outcome === 'ok' ? 'success' : 'error'}>
            <strong>Resultado: </strong>
            {data.mens}
          </Alert>
        </div>

        <Card title="Detalle del pago">
          <Grid columns={2}>
            <div data-field="RORDEN">
              <TextField
                label="Orden"
                hint="Número de orden, 7 dígitos"
                maxLength={7}
                value={formatOrden(data.orden)}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="RCOMIS">
              <TextField
                label="Comisión"
                hint="Formato ZZZ,ZZ9.99"
                maxLength={10}
                value={formatComis(data.comis)}
                onChange={() => {}}
                readOnly
              />
            </div>
            <div data-field="RMOVIM">
              <TextField
                label="Movimiento"
                hint="Número de movimiento, hasta 10 dígitos"
                maxLength={10}
                value={formatMovim(data.movim)}
                onChange={() => {}}
                readOnly
              />
            </div>
          </Grid>
          <Row>
            <Badge>{outcome === 'ok' ? 'Pago aplicado' : 'Pago rechazado'}</Badge>
          </Row>
        </Card>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={newPayment}>
            Nuevo pago
          </Button>
          <Button variant="secondary" shortcut="PF3" onClick={goMenu}>
            Menú
          </Button>
        </Row>

        <Card title="Vista previa del prototipo">
          <SelectField
            label="Estado a simular"
            hint="Solo para la revisión: no forma parte de la pantalla"
            options={[
              { value: 'ok', label: 'Pago aplicado' },
              { value: 'rejected', label: 'Pago rechazado' },
            ]}
            value={outcome}
            onChange={(v: string) => setOutcome(v as Outcome)}
          />
        </Card>
      </Stack>
    </Screen>
  );
}
